
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ft98_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ft98", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.495653933394948e+00, -4.415298869564084e+00, -4.301835624443677e+00, -4.144669613488011e+00, -3.935658215291676e+00, -3.681435978056728e+00, -3.228510906421788e+00, -2.695572315169966e+00, -2.143769790554080e+00, -1.577572474687167e+00, -1.035707170030961e+00, -7.044996457112500e-01, -6.143984689995127e-01, -5.073160675455679e-01, -3.659981418465171e-01, -2.324688889869375e-01, -1.316909000426909e-01, -7.207013885060966e-02, -4.703644287673098e-02, -3.241815204002783e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


